  "inlineSchema": "// prisma/schema.prisma\n// 与 db/schema.sql 保持一致，新增 Prisma 关系定义\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── 用户 ────────────────────────────────────────────────\nmodel User {\n  id            Int      @id @default(autoincrement()) @db.UnsignedInt\n  openId        String   @unique @map(\"open_id\") @db.VarChar(64)\n  // 预留字段，TODO 2：扩展到多端时做 OpenID→UnionID 迁移\n  unionId       String?  @map(\"union_id\") @db.VarChar(64)\n  nickname      String   @default(\"\") @db.VarChar(64)\n  avatarUrl     String   @default(\"\") @map(\"avatar_url\") @db.VarChar(512)\n  notifyEnabled Boolean  @default(false) @map(\"notify_enabled\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  pet        Pet?\n  notifyLogs NotifyLog[]\n\n  @@index([unionId])\n  @@map(\"users\")\n}\n\n// ─── 宠物 ────────────────────────────────────────────────\nmodel Pet {\n  id      Int        @id @default(autoincrement()) @db.UnsignedInt\n  userId  Int        @unique @map(\"user_id\") @db.UnsignedInt // MVP：一人一宠\n  name    String     @db.VarChar(32)\n  species PetSpecies @default(cat)\n\n  originalImageUrl String      @default(\"\") @map(\"original_image_url\") @db.VarChar(512)\n  stylizedImageUrl String      @default(\"\") @map(\"stylized_image_url\") @db.VarChar(512)\n  imageStyle       String      @default(\"\") @map(\"image_style\") @db.VarChar(32)\n  imageStatus      ImageStatus @default(pending) @map(\"image_status\")\n  imageUpdatedAt   DateTime?   @map(\"image_updated_at\")\n\n  // stats 存 JSON：{ satiety, cleanliness, happiness } 均 ∈ [5, 100]\n  // 读取时用 parseStats() 做 schema 校验 + 默认值兜底（CRITICAL 修复）\n  stats Json @default(\"{\\\"satiety\\\":100,\\\"cleanliness\\\":100,\\\"happiness\\\":100}\")\n\n  lastCronAt DateTime @default(now()) @map(\"last_cron_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  user              User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  dailyInteractions DailyInteraction[]\n  notifyLogs        NotifyLog[]\n\n  @@map(\"pets\")\n}\n\nenum PetSpecies {\n  cat\n  dog\n  other\n}\n\n// image_status 状态机：\n//   pending → processing（AI 调用中）→ done（完成）\n//                                     → failed（超时/失败，可重试）\nenum ImageStatus {\n  pending\n  processing\n  done\n  failed\n}\n\n// ─── 每日互动记录 ─────────────────────────────────────────\nmodel DailyInteraction {\n  id               Int             @id @default(autoincrement()) @db.UnsignedInt\n  petId            Int             @map(\"pet_id\") @db.UnsignedInt\n  interactionType  InteractionType @map(\"interaction_type\")\n  interactionDate  DateTime        @map(\"interaction_date\") @db.Date\n  count            Int             @default(1) @db.UnsignedTinyInt\n  statsDelta       Json?           @map(\"stats_delta\")\n  lastInteractedAt DateTime        @default(now()) @map(\"last_interacted_at\")\n  createdAt        DateTime        @default(now()) @map(\"created_at\")\n\n  pet Pet @relation(fields: [petId], references: [id], onDelete: Cascade)\n\n  @@unique([petId, interactionType, interactionDate])\n  @@index([petId, interactionDate])\n  @@map(\"daily_interactions\")\n}\n\nenum InteractionType {\n  feed\n  pet_action\n  play\n}\n\n// ─── 微信推送日志 ─────────────────────────────────────────\nmodel NotifyLog {\n  id            Int        @id @default(autoincrement()) @db.UnsignedInt\n  userId        Int        @map(\"user_id\") @db.UnsignedInt\n  petId         Int        @map(\"pet_id\") @db.UnsignedInt\n  notifyType    NotifyType @default(low_stats) @map(\"notify_type\")\n  sentAt        DateTime   @default(now()) @map(\"sent_at\")\n  statsSnapshot Json?      @map(\"stats_snapshot\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  pet  Pet  @relation(fields: [petId], references: [id], onDelete: Cascade)\n\n  @@index([petId, notifyType, sentAt])\n  @@index([userId, sentAt])\n  @@map(\"notify_logs\")\n}\n\nenum NotifyType {\n  low_stats\n  welcome\n  daily_remind\n}\n",
